              <Label
                htmlFor="prompt"
                className="shrink-0 text-xs font-medium text-muted-foreground"
              >
                Prompt del sistema
              </Label>
              <Textarea
                id="prompt"
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                className="min-h-[200px] flex-1 resize-none border-border/40 bg-muted/20 font-mono text-xs leading-relaxed text-foreground focus-visible:ring-1 focus-visible:ring-primary/40 md:min-h-[300px]"
                placeholder="Escribe las instrucciones personalizadas aquí..."
              />
            </div>
          </div>

          <DialogFooter className="mt-4 shrink-0 flex-col gap-2 border-t border-border/40 pt-3 sm:flex-row sm:gap-2">
            <Button
              variant="ghost"
              onClick={() => {
                resetSystemPrompt()
                setIsOpen(false)
              }}
              className="w-full text-xs text-muted-foreground hover:text-destructive sm:w-auto"
            >
              Restaurar valores por defecto
            </Button>
            <Button
              onClick={handleSave}
              className="w-full px-6 text-xs font-medium sm:w-auto"
            >
              Aplicar cambios
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* AlertDialog de ShadCN para confirmaciones de eliminación */}
      <AlertDialog
        open={templateToDelete !== null}
        onOpenChange={(open) => {
          if (!open && !isDeleting) setTemplateToDelete(null)
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>¿Eliminar plantilla?</AlertDialogTitle>
            <AlertDialogDescription>
              Se eliminará permanentemente la plantilla{" "}
              <strong className="text-foreground">
                “{templateToDelete?.replace(".md", "")}”
              </strong>
              . Esta acción no se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeleting}>
              Cancelar
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={(e) => {
                e.preventDefault()
                handleConfirmDelete()
              }}
              disabled={isDeleting}
              className="text-destructive-foreground bg-destructive hover:bg-destructive/90"
            >
              {isDeleting ? "Eliminando..." : "Eliminar"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

